1	package posemap
2	
3	import (
4		"errors"
5		"os"
6		"path/filepath"
7		"testing"
8	)
9	
10	// buildCorrectedMap 构造含三帧（t=100、200、300）并对 t=100 做过一次校正
11	// 的地图，校正记录覆盖全部三帧。
12	func buildCorrectedMap(t *testing.T, path string) {
13		t.Helper()
14		m, err := Create(path, baseConfig())
15		if err != nil {
16			t.Fatal(err)
17		}
18		if _, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{
19			{Time: 100, DX: 1},
20			{Time: 200, DX: 1},
21			{Time: 300, DX: 1},
22		}}); err != nil {
23			t.Fatal(err)
24		}
25		if _, err := m.Correct(Correction{ID: "c1", Anchor: 100, Target: CorrectionTarget{X: 5, Y: 6, Variance: 1}}); err != nil {
26			t.Fatal(err)
27		}
28		if err := m.Close(); err != nil {
29			t.Fatal(err)
30		}
31	}
32	
33	// tamperFile 读取文件、按 fn 篡改后重算校验和写回。
34	func tamperFile(t *testing.T, path string, fn func(fd *fileData)) {
35		t.Helper()
36		fd := readFileData(t, path)
37		fn(&fd)
38		writeFileDataRaw(t, path, &fd)
39	}
40	
41	// assertOpenCorrupt 断言 Open 以 ErrCorrupt 拒绝、不返回地图对象且文件
42	// 内容保持不变。
43	func assertOpenCorrupt(t *testing.T, path string) {
44		t.Helper()
45		before, err := os.ReadFile(path)
46		if err != nil {
47			t.Fatal(err)
48		}
49		m, err := Open(path)
50		if !errors.Is(err, ErrCorrupt) {
51			t.Fatalf("err = %v, want ErrCorrupt", err)
52		}
53		if m != nil {
54			t.Fatalf("map = %v, want nil", m)
55		}
56		after, err := os.ReadFile(path)
57		if err != nil {
58			t.Fatal(err)
59		}
60		if string(before) != string(after) {
61			t.Fatal("file modified by rejected Open")
62		}
63	}
64	
65	// 校正记录必须恰好覆盖声明范围内的每一帧：缺失、重复、错序、范围外的
66	// 额外条目、前后时间不一致，或锚点/结束时间不命中已导入帧，都按损坏
67	// 拒绝。
68	func TestOpenRejectsIncompleteCorrectionRecords(t *testing.T) {
69		cases := []struct {
70			name string
71			fn   func(fd *fileData)
72		}{
73			{"missing middle frame", func(fd *fileData) {
74				p := fd.Corrections[0].Poses
75				fd.Corrections[0].Poses = []poseChangeJSON{p[0], p[2]}
76			}},
77			{"missing last frame", func(fd *fileData) {
78				fd.Corrections[0].Poses = fd.Corrections[0].Poses[:2]
79			}},
80			{"duplicate frame replaces another", func(fd *fileData) {
81				fd.Corrections[0].Poses[1] = fd.Corrections[0].Poses[0]
82			}},
83			{"out of order", func(fd *fileData) {
84				p := fd.Corrections[0].Poses
85				p[0], p[1] = p[1], p[0]
86			}},
