8	// buildVarianceCorrectedMap 构造三帧（t=100、200、300）并对 t=100 做过一次
9	// 校正的地图：进入三帧的原运动方差依次为 0.25、0.25、0.5，目标方差为 1，
10	// 故三帧校正后方差依次为 1、1.25、1.75（锚点自身的 0.25 不再累加）。
11	func buildVarianceCorrectedMap(t *testing.T, path string) {
12		t.Helper()
13		m, err := Create(path, baseConfig())
14		if err != nil {
15			t.Fatal(err)
16		}
17		if _, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{
18			{Time: 100, DX: 1, MoveVariance: 0.25},
19			{Time: 200, DX: 1, MoveVariance: 0.25},
20			{Time: 300, DX: 1, MoveVariance: 0.5},
21		}}); err != nil {
22			t.Fatal(err)
23		}
24		if _, err := m.Correct(Correction{ID: "c1", Anchor: 100,
25			Target: CorrectionTarget{X: 5, Y: 6, Variance: 1}}); err != nil {
26			t.Fatal(err)
27		}
28		if err := m.Close(); err != nil {
29			t.Fatal(err)
30		}
31	}
32	
33	// 正常文件：校正后方差逐帧等于“目标方差 + 锚点之后原运动方差累计”，
34	// 锚点自身的运动方差不重复累加；重开后记录与查询都保持该结果。
35	func TestOpenAcceptsCorrectedVarianceAccumulation(t *testing.T) {
36		path := filepath.Join(t.TempDir(), "m.pose")
37		buildVarianceCorrectedMap(t, path)
38		m, err := Open(path)
39		if err != nil {
40			t.Fatalf("open: %v", err)
41		}
42		defer m.Close()
43		recs, err := m.Corrections()
44		if err != nil {
45			t.Fatal(err)
46		}
47		if len(recs) != 1 || len(recs[0].Poses) != 3 {
48			t.Fatalf("records = %+v", recs)
49		}
50		want := []float64{1, 1.25, 1.75}
51		for i, v := range want {
52			if got := recs[0].Poses[i].After.Variance; got != v {
53				t.Fatalf("pose %d after variance = %v, want %v", i, got, v)
54			}
55		}
56	}
57	
58	// 只有锚点一帧的记录：校正后方差等于目标方差即可；被篡改即损坏。
59	func TestOpenChecksSingleFrameCorrectionVariance(t *testing.T) {
60		path := filepath.Join(t.TempDir(), "m.pose")
61		m, err := Create(path, baseConfig())
62		if err != nil {
63			t.Fatal(err)
64		}
65		if _, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{
66			{Time: 100, DX: 1, MoveVariance: 0.4},
67			{Time: 200, DX: 1, MoveVariance: 0.6},
68		}}); err != nil {
69			t.Fatal(err)
70		}
71		if _, err := m.Correct(Correction{ID: "c1", Anchor: 200,
72			Target: CorrectionTarget{X: 5, Y: 6, Variance: 2}}); err != nil {
73			t.Fatal(err)
74		}
75		if err := m.Close(); err != nil {
76			t.Fatal(err)
77		}
78	
79		// 未篡改：唯一一帧校正后方差恰为目标方差，正常打开。
80		m2, err := Open(path)
81		if err != nil {
82			t.Fatalf("open: %v", err)
83		}
84		recs, _ := m2.Corrections()
85		if len(recs) != 1 || recs[0].Poses[0].After.Variance != 2 {
86			t.Fatalf("records = %+v", recs)
87		}
88		m2.Close()
89	
90		tamperFile(t, path, func(fd *fileData) {
91			fd.Corrections[0].Poses[0].After.Variance = 2.6
92		})
93		assertOpenCorrupt(t, path)
94	}
95	
96	// 逐帧核对：锚点与末帧正确但中间帧错误、或任意一帧与累计规则不符，都按
97	// 损坏拒绝；以校正前方差为起点等错误写法同样被拒。
98	func TestOpenRejectsInconsistentCorrectedVariances(t *testing.T) {
99		cases := []struct {
100			name string
101			fn   func(fd *fileData)
102		}{
103			{"anchor variance differs from target", func(fd *fileData) {
104				fd.Corrections[0].Poses[0].After.Variance = 1.1
105			}},
106			{"middle frame wrong while anchor and last are right", func(fd *fileData) {
107				fd.Corrections[0].Poses[1].After.Variance = 1.3
108			}},
109			{"last frame wrong", func(fd *fileData) {
110				fd.Corrections[0].Poses[2].After.Variance = 1.7
111			}},
112			{"anchor adds its own motion variance once more", func(fd *fileData) {
113				// 1.25 = 目标 1 + 锚点自身运动方差 0.25：锚点不得再加一次。
114				fd.Corrections[0].Poses[0].After.Variance = 1.25
115			}},
116			{"accumulated from pre-correction variance", func(fd *fileData) {
117				// 以校正前方差（初始 0.5 累计到 0.75/1.0/1.5）为起点是错的：
118				// 必须以目标方差 1 为起点。
119				p := fd.Corrections[0].Poses
120				p[0].After.Variance, p[1].After.Variance, p[2].After.Variance = 0.75, 1.0, 1.5
121			}},
122			{"negative corrected variance", func(fd *fileData) {
123				fd.Corrections[0].Poses[1].After.Variance = -0.01
124			}},
125			{"negative target variance", func(fd *fileData) {
126				fd.Corrections[0].Target.Variance = -0.5
127			}},
128			{"saved motion variance changed", func(fd *fileData) {
129				// 锚点之后第一帧（t=200）的原运动方差被改为 0.3：真实累计
130				// 应为 1.3，与保存的 1.25 矛盾。
131				fd.Sources[1].MoveVariance = 0.3
132			}},
