10	// 输入全部为有限数值时，导入推演仍可能产生非有限结果：位置叠加、朝向
11	// 累计、方差累计溢出。这些情况必须按 non_finite 拒绝并指出从零开始的
12	// 帧序号，而不是在保存时返回普通编码错误。
13	func TestImportComputedNonFinitePose(t *testing.T) {
14		huge := func() Config {
15			return Config{
16				InitialTime: 0, InitialX: 1e308, InitialY: 0, InitialHeading: 0,
17				InitialVariance: 0, MaxInterval: 100, MergeDistance: 10,
18			}
19		}
20		type tc struct {
21			name   string
22			cfg    Config
23			frames []Frame
24			frame  int
25		}
26		cases := []tc{
27			{
28				name:   "position overflow on first frame",
29				cfg:    huge(),
30				frames: []Frame{{Time: 1, DX: 1e308}}, // 1e308 + 1e308 = +Inf
31				frame:  0,
32			},
33			{
34				name: "position overflow on later frame",
35				cfg:  huge(),
36				frames: []Frame{
37					{Time: 1}, // 1e308+1 舍入为 1e308，仍有限
38					{Time: 2},
39					{Time: 3, DX: 1e308}, // 这一帧才溢出
40				},
41				frame: 2,
42			},
43			{
44				name: "variance accumulation overflow",
45				cfg: func() Config {
46					c := huge()
47					c.InitialX = 0
48					c.InitialVariance = 1e308
49					return c
50				}(),
51				frames: []Frame{{Time: 1, MoveVariance: 1e308}}, // 1e308+1e308 = +Inf
52				frame:  0,
53			},
54			{
55				name: "heading accumulation overflow",
56				cfg: func() Config {
57					c := huge()
58					c.InitialX = 0
59					c.InitialHeading = 1e308
60					return c
61				}(),
62				frames: []Frame{{Time: 1, DHeading: 1e308}}, // 归一化后为 NaN
63				frame:  0,
64			},
65		}
66		for _, c := range cases {
67			t.Run(c.name, func(t *testing.T) {
68				m := newMap(t, c.cfg)
69				_, err := m.ImportSegment(Segment{ID: "s", Frames: c.frames})
70				r, ok := AsRejectError(err)
71				if !ok {
72					t.Fatalf("err = %v, want *RejectError", err)
73				}
74				if r.Kind != RejectNonFinite || !r.HasFrame || r.Frame != c.frame {
75					t.Fatalf("got kind=%q frame=%d(ok=%v), want non_finite frame %d", r.Kind, r.Frame, r.HasFrame, c.frame)
76				}
77				if r.HasLandmark {
78					t.Fatalf("pose rejection unexpectedly carries landmark %q", r.Landmark)
79				}
80				// 拒绝后当前位姿仍是初始位姿。
81				cur, _ := m.CurrentPose()
82				if cur.Time != 0 {
83					t.Fatalf("current time = %d, state leaked after rejection", cur.Time)
84				}
85			})
86		}
87	}
