90	// 与有效记录（段内暂存或已提交记录）合并，都按 non_finite 拒绝并携带
91	// 路标标识；转换结果有限但超过合并距离时仍是原来的距离冲突。
92	func TestImportComputedNonFiniteObservation(t *testing.T) {
