155			// 失效后再次出现：转换溢出同样按数值异常拒绝。
156			_, err := m.ImportSegment(Segment{ID: "s2", Frames: []Frame{
157				{Time: 2, Observations: []Observation{{ID: "L", X: 1e308}}},
158			}})
159			rejectKind(t, err, RejectNonFinite, 0, "L")
160			h, _ := m.LandmarkAppearances("L")
161			if len(h.Appearances) != 1 || h.Appearances[0].Active {
162				t.Fatalf("rejection consumed an occurrence number: %+v", h)
163			}
164		})
